import java.util.Vector;

public class Voti {
    private Vector<Integer> v = new Vector<>();

    public void aggiungi(int x) {
        v.add(x);
    }

    public int quanti() {
        return v.size();
    }

    public int leggi(int i) {
        return v.get(i);
    }
}

public class Main {
    public static void main(String[] args) {
        Voti voti = new Voti();
        voti.aggiungi(7);
        voti.aggiungi(9);
        System.out.println(voti.quanti());
        System.out.println(voti.leggi(1));
    }
}
